class Storeroom:
    def __init__(self, label):
        self.label = label
        self.items = []

    def add_item(self, item):
        self.items.append(item)
        print(f"Added {item} to {self.label}.")

    def report(self):
        print(f"{self.label} holds {len(self.items)} item(s).")


class VaultStoreroom(Storeroom):
    def __init__(self, label, clearance):
        super().__init__(label)
        self.clearance = clearance

    def add_item(self, item):
        print(f"Storing {item} under clearance {self.clearance}.")
        self.items.append(item)

    def report(self):
        print(f"{self.label} holds {len(self.items)} item(s). Clearance required: {self.clearance}.")


vault = VaultStoreroom("North Vault", "gamma")
vault.report()
vault.add_item("iron bar")
vault.report()
